export const questIndex = new Map(quests.map((quest) => [quest.id, quest]));

export function findQuestById(id) {
  return questIndex.get(id);
}

export function listQuestsByTier(tier) {
  return quests.filter((quest) => quest.tier === tier);
}

export function getExercise(slug) {
  return exercises[slug];
}
